local route = {
  {-440, -2627, 179, -1, 0},
  {-454, -2620, 178, -1, 0},
  {-1204, -2682, 151, -1, 0},
  {-1825, -1705, 165, -1, 0},
}
local leg = 0
local finished = false
local function route_heading(npc,p)
  if p[4] ~= -1 then return p[4] end
  local dx,dy = p[1]-npc:GetX(),p[2]-npc:GetY()
  if dx == 0 and dy == 0 then return npc:GetHeading() end
  return (math.atan2(dx,dy)*512/(2*math.pi)+512)%512
end

local function walk(e)
  e.self:SetRunning(false)
  local p=route[leg]; e.self:MoveTo(p[1],p[2],p[3],route_heading(e.self,p),true)
end
function event_spawn(e) if not finished and leg == 0 then leg = 1; walk(e) end end
function event_waypoint_depart(e)
  if finished or leg == 0 then return end
  if leg == #route then finished = true; eq.depop(); return end
  leg = leg + 1; walk(e)
end
function event_death_complete(e) finished = true end
function event_trade(e) require("items").return_items(e.self,e.other,e.trade) end
